// Turn the Knowledge sheet (type, name, details, price, allergens, dietary) into text for the AI
const rows = $input.all().map(i => i.json).filter(r => r.name || r.details);
const isMenu = r => String(r.type || '').trim().toLowerCase() === 'menu';
const menu = rows.filter(isMenu).map(r => `- ${r.name}${r.price ? ' (' + r.price + ')' : ''}: ${r.details || ''}` +
  `${r.allergens ? ' | Allergens: ' + r.allergens : ' | Allergens: not listed'}${r.dietary ? ' | ' + r.dietary : ''}`);
const info = rows.filter(r => !isMenu(r)).map(r => `- ${r.name}: ${r.details || ''}`);
const msg = $('Receive Telegram message').first().json.message || {};
return [{ json: {
  chat_id: msg.chat?.id, message_id: msg.message_id, first_name: msg.from?.first_name || '',
  username: msg.from?.username || '', question: String(msg.text || '(sent something that is not text)').slice(0, 1000),
  today: $now.toFormat('cccc yyyy-MM-dd'),
  calendar: Array.from({ length: 21 }, (_, i) => $now.plus({ days: i }).toFormat('ccc d LLL = yyyy-MM-dd')).join('; '),
  knowledge: `MENU\n${menu.join('\n') || '(no menu items)'}\n\nINFORMATION\n${info.join('\n') || '(no information)'}`,
} }];

// Allergen and diet filter: the AI only ever sees dishes that fit the customer's stated needs
// (UK/EU 14 allergens + vegan / vegetarian / halal / kosher). Matching uses your allergens and dietary columns, never AI guesses.
const kb = $input.first().json;
const q = String(kb.question || '').toLowerCase();
const ALLERGENS = {
  gluten: /gluten|coeliac|celiac|wheat|barley|\brye\b|spelt/, crustaceans: /crustacean|shellfish|prawn|shrimp|crab|lobster/,
  eggs: /\beggs?\b/, fish: /\bfish\b|anchov|salmon|tuna|\bcod\b/, peanuts: /peanut|groundnut|\bnuts?\b/,
  'tree nuts': /tree ?nuts?|\bnuts?\b|almond|hazelnut|walnut|cashew|pistachio|pecan|macadamia/,
  milk: /\bmilk|dairy|lactose|cheese|cream|butter/, soya: /\bsoy/, sesame: /sesame/, celery: /celery|celeriac/,
  mustard: /mustard/, lupin: /lupin/, molluscs: /mollusc|shellfish|mussel|oyster|squid|clam|scallop|octopus/,
  sulphites: /sulphite|sulfite|sulphur|sulfur/,
};
const DIETS = { vegan: /\bvegan|plant[- ]based/, vegetarian: /vegetarian|\bveggie/, halal: /\bhalal/, kosher: /\bkosher/ };
// An allergen word only counts as a need with an allergy cue ("Do you have fish?" is a menu question, "no fish" is a need)
const cue = /allerg|intoleran|coeliac|celiac|sensitiv|can'?t (eat|have)|cannot (eat|have)|don'?t eat|avoid|[a-z][- ]?free\b|\bfree from|without|\bno [a-z]/.test(q);
const avoid = cue ? Object.keys(ALLERGENS).filter(k => ALLERGENS[k].test(q)) : [];
const diets = Object.keys(DIETS).filter(k => DIETS[k].test(q));
const needs = [...avoid.map(a => 'no ' + a), ...diets];
if (!needs.length) return [{ json: { ...kb, has_filter: false, no_match: false, knowledge_for_ai: kb.knowledge, needs_note: '' } }];

const rows = $('Read menu and FAQ sheet').all().map(i => i.json).filter(r => String(r.type || '').trim().toLowerCase() === 'menu' && r.name);
const fits = (r, need) => {
  const al = String(r.allergens || '').toLowerCase(), tags = String(r.dietary || '').toLowerCase();
  if (need.startsWith('no ')) {
    const a = need.slice(3);
    if (!al.trim()) return 'unknown';                       // no allergen info: never offered as suitable
    if (a === 'gluten' && /gluten[- ]free/.test(tags)) return true;
    return !ALLERGENS[a].test(al.replace(/gluten[- ]free/g, ''));
  }
  if (need === 'vegetarian') return /vegetarian|vegan/.test(tags);
  return new RegExp(need).test(tags);
};
const ok = rows.filter(r => needs.every(n => fits(r, n) === true));
const unknown = rows.filter(r => !ok.includes(r) && needs.some(n => fits(r, n) === 'unknown')).map(r => r.name);
const perNeed = needs.map(n => `${n}: ${rows.filter(r => fits(r, n) === true).map(r => r.name).join(', ') || 'nothing on the menu'}`);
const line = r => `- ${r.name}${r.price ? ' (' + r.price + ')' : ''}: ${r.details || ''} | Allergens: ${r.allergens}${r.dietary ? ' | ' + r.dietary : ''}`;
const info = String(kb.knowledge).split('\n\nINFORMATION\n')[1] || '(no information)';
const s = $('Set restaurant details').first().json;
return [{ json: { ...kb, has_filter: true, needs: needs.join(', '), no_match: ok.length === 0,
  knowledge_for_ai: `MENU (only dishes that fit: ${needs.join(', ')}; dishes that don't fit were removed)\n${ok.map(line).join('\n') || '(none)'}\n\nINFORMATION\n${info}`,
  needs_note: `The customer said they need: ${needs.join(', ')}. The menu below has already been filtered to the dishes that fit. Recommend only these.` +
    (unknown.length ? ` These dishes have no allergen information, so tell them to ask staff: ${unknown.join(', ')}.` : ''),
  no_match_reply: `Sorry ${kb.first_name || ''}, going by our allergen list nothing on the menu fits all of these together: ${needs.join(', ')}.\n` +
    perNeed.map(x => '• ' + x).join('\n') +
    (unknown.length ? `\nNo allergen info yet for: ${unknown.join(', ')}.` : '') +
    `\nPlease call us on ${s.phone} and the kitchen will see what they can do.`,
} }];

