// Fixed safety line after any allergy or diet answer (written by you, not the AI)
const c = $('Check allergy and diet needs').first().json;
const note = c.has_filter ? `\n\n(Checked against our allergen list for: ${c.needs}. Please always tell staff about allergies when you order.)` : '';
return [{ json: { chat_id: c.chat_id, text: String($input.first().json.text || '').trim() + note } }];
